from java.lang import Throwable

def isdict(v):
	try:
		v.keys()
		return True
	except Throwable:
		return False
	except:
		return False

def islist(v):
	if isdict(v) or isinstance(v, basestring):
		return False
	try:
		len(v)
		iter(v)
		return True
	except:
		return False

def led(ok):
	if ok is None:
		return "na"
	if ok:
		return "ok"
	return "bad"

def pick(it, keys):
	for k in keys:
		v = it.get(k)
		if v is not None and str(v) != "":
			return v
	return None

def one(it):
	if isdict(it):
		nm = pick(it, ("title", "name", "item", "step", "label", "key"))
		ok = pick(it, ("ok", "present", "done", "installed", "healthy"))
		st = pick(it, ("detail", "state", "status", "message", "value"))
		if st is None:
			if ok is None:
				st = ""
			elif ok:
				st = "OK"
			else:
				st = "MISSING"
		if nm is None:
			nm = ""
		return {"name": str(nm), "state": str(st), "led": led(ok)}
	return {"name": str(it), "state": "", "led": "na"}

def findlist(d, depth):
	if depth > 4:
		return None
	if islist(d):
		return d
	if not isdict(d):
		return None
	for k in ("items", "checks", "rows", "results", "steps"):
		if islist(d.get(k)):
			return d.get(k)
	for k in d.keys():
		r = findlist(d.get(k), depth + 1)
		if r is not None:
			return r
	return None

def flatten(d):
	rows = []
	if not isdict(d):
		return rows
	keys = [str(k) for k in d.keys()]
	keys.sort()
	for k in keys:
		v = d.get(k)
		if isdict(v):
			rows.extend(flatten(v))
		elif islist(v):
			rows.append({"name": k, "state": "%d entries" % len(v), "led": "na"})
		else:
			txt = str(v)
			ok = None
			if v is True or txt.lower() in ("ok", "true", "yes", "ready", "installed"):
				ok = True
			elif v is False or txt.lower() in ("false", "no", "missing", "error", "failed"):
				ok = False
			rows.append({"name": k, "state": txt, "led": led(ok)})
	return rows

def rowify(d):
	lst = findlist(d, 0)
	if lst:
		return [one(it) for it in lst]
	return flatten(d)

out = {"msg": "", "raw": "", "rows": []}
try:
	# In-process, as the logged-in Perspective session: no HTTP hop
	# back to an open route, so this works with the write route shut.
	# The encode/decode round trip is deliberate - it hands rowify()
	# exactly the object the HTTP response used to.
	data = system.util.jsonDecode(system.util.jsonEncode({"ok": True, "check": MachineDemo.setup.check()}))
	out["msg"] = "check -> OK"
	if data is None:
		out["raw"] = ""
	else:
		try:
			out["raw"] = system.util.jsonEncode(data, 1)[:1400]
		except:
			out["raw"] = str(data)[:1400]
		out["rows"] = rowify(data)
except Throwable, e:
	out["msg"] = "check -> FAILED"
	out["raw"] = str(e)[:1400]
except Exception, e:
	out["msg"] = "check -> FAILED"
	out["raw"] = str(e)[:1400]
# The view carries ROWS fixed rows, so the list is padded to exactly that.
# Truncating in silence is how this screen came to show six of the eight
# checks setup.check() actually runs - the alarm journal and the cell
# simulation fell off the end and nothing said so. If there is ever an
# overflow again it goes in the message rather than into the dark.
ROWS = 8
rows = out["rows"]
extra = len(rows) - ROWS
while len(rows) < ROWS:
	rows.append({"name": "", "state": "", "led": "blank"})
if extra > 0:
	out["msg"] = "%s (+%d not shown)" % (out["msg"], extra)
out["rows"] = rows[:ROWS]
self.view.custom.check = out

